// Actual executable regression against isolated JSON stores; routed button tests are not native mouse input.
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Automation;
using System.Windows.Threading;
using Ivad.Ids;
namespace Ivad.Annotator {
 public sealed partial class MainWindow {
  Store BatchFixture(string root,int count,bool protectedFrames=false){
   var s=Fixture(root,2);if(s.Data.entities.Count(e=>e.kind=="Frame")==count)return s;
   var fs=s.Data.entities.Where(e=>e.kind=="Frame").ToList();string video=s.Data.entities.First(e=>e.kind=="Video").id;s.Find(video).data["original_name"]="Night.mp4";
   for(int i=2;i<count;i++){var f=Codec.Parse<Entity>(Codec.Json(fs[0]));f.id=Guid.NewGuid().ToString();s.Data.entities.Add(f);fs.Add(f);}
   for(int i=0;i<count;i++){fs[i].data["video_id"]=video;fs[i].data["pts_us"]=(long)i*1000000;fs[i].data["source_timestamp_100ns"]=(long)i*10000000;}
   s.Save();
   if(protectedFrames){
    s.MarkNormalBatch(fs.Take(204).Select(f=>f.id),"fixture");string fault=s.Data.entities.First(e=>e.kind=="Fault").id;
    s.AddGeometryCurrent(fs[900].id,fault,"box",new[]{1.0,1,20,20},false);s.ReviewCurrent(fs[900].id,"abnormal","confirmed","fixture");
    s.AddGeometryCurrent(fs[1100].id,fault,"polygon",new[]{2.0,2,25,2,25,25},false);s.ReviewCurrent(fs[1100].id,"abnormal","confirmed","fixture");
    s.ReviewCurrent(fs[1799].id,"normal","confirmed","fixture");
    s.AddGeometryCurrent(fs[950].id,"","polygon",new[]{3.0,3,28,3,28,28},true);
   }
   return s;
  }
  void ShowBatchFixture(Store s){reviewEdited=false;polygon.Clear();start=null;Use(s);Navigate("标注与审核");frameVideoFilter.SelectedIndex=0;frameStateFilter.SelectedIndex=0;Show();UpdateLayout();Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));}
  void BatchClick(){var b=Elements(Content as DependencyObject).OfType<Button>().Single(e=>AutomationProperties.GetName(e)=="批量标记正常");b.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));}
  static int DiskConfirmed(Store s){return s.Data.entities.Where(e=>e.kind=="Review").GroupBy(e=>e.Text("frame_id")).Count(g=>g.Last().Text("status")=="confirmed");}
  static void AssertBatchDisk(Store s,IEnumerable<string> ids){var reviews=s.Data.entities.Where(e=>e.kind=="Review").GroupBy(e=>e.Text("frame_id")).ToDictionary(g=>g.Key,g=>g.Last());foreach(var id in ids){Check(s.Find(id).Text("state")=="normal","saved normal "+id);Check(reviews.ContainsKey(id)&&reviews[id].Text("status")=="confirmed","saved confirmed "+id);}}
  public void OpenBatchNormalFixture(string root){ShowBatchFixture(BatchFixture(Path.GetFullPath(root),1800,true));frames.SelectedIndex=1799;frames.SelectRange(875,1799,false);frames.ScrollIntoView(frames.Items[1799]);Title="IVAD 批量正常925帧独立测试";}
  public int BatchNormalChecks(string output,bool reopen){
   System.Threading.SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher));output=Path.GetFullPath(output);
   if(!reopen&&Directory.Exists(output)&&Directory.EnumerateFileSystemEntries(output).Any())throw new IOException("批量回归只允许全新独立目录");Directory.CreateDirectory(output);
   var results=new List<object>();int failed=0;string root=Path.Combine(output,"925");
   Action<string,Action> test=(name,action)=>{try{action();results.Add(new{name=name,status="PASS"});}catch(Exception e){failed++;results.Add(new{name=name,status="FAIL",error=e.ToString()});}File.WriteAllText(Path.Combine(output,reopen?"reopen-results.json":"results.json"),Codec.Json(new{passed=results.Count-failed,failed=failed,scope="Actual Release EXE; independent JSON store persisted and reopened; WPF routed Click NOT native mouse",executable=System.Reflection.Assembly.GetEntryAssembly().Location,tests=results}));};
   if(reopen){
    test("new-process/reopen-925-state-audit-and-count",()=>{var s=new Store(root);var expected=Codec.Parse<Dictionary<string,object>>(File.ReadAllText(Path.Combine(output,"expected.json")));Check(Codec.Fingerprint(s.Data)==Convert.ToString(expected["fingerprint"]),"new process exact persisted fingerprint");Check(DiskConfirmed(s)==1129,"207 + 922 confirmed");ShowBatchFixture(s);Check(frameSummary.Text=="已确认 1129 / 1800","new-process UI matches storage");var ids=orderedFrames.Skip(875).Select(e=>e.id).ToArray();string before=Codec.Fingerprint(s.Data);frames.SelectedIndex=1799;frames.SelectRange(875,1799,false);BatchClick();WaitHotfix();Check(lastBatchResult.Success==0&&lastBatchResult.Skipped==925&&before==Codec.Fingerprint(new Store(root).Data),"repeated after restart no duplicate audit");});
   }else{
    var s=BatchFixture(root,1800,true);var all=s.Data.entities.Where(e=>e.kind=="Frame").OrderBy(e=>e.Number("pts_us")).ToArray();var targets=all.Skip(875).Select(e=>e.id).ToArray();
    test("root-cause/old-strict-batch-rejects-mixed-925",()=>{Check(targets.Length==925&&all[875].Number("pts_us")==875000000&&all[1799].Number("pts_us")==1799000000,"timestamps are seconds, not one-based frame numbers");Check(DiskConfirmed(s)==207,"matches original confirmation count");string before=Codec.Fingerprint(s.Data);bool rejected=false;try{s.MarkNormalBatch(targets,"test");}catch(InvalidDataException){rejected=true;}Check(rejected&&before==Codec.Fingerprint(new Store(root).Data),"exact strict all-or-nothing failure reproduced");});
    foreach(int count in new[]{1,3})test("batch/"+count+"-frames-unique-UUIDs-and-single-commit",()=>{var f=BatchFixture(Path.Combine(output,"small-"+count),6);ShowBatchFixture(f);frames.SelectedIndex=5;frames.SelectRange(0,count-1,false);string[] ids=frames.SelectionIds();long seq=f.Data.sequence;BatchClick();Check(busy,"handler returns while task runs off dispatcher");WaitHotfix();var disk=new Store(f.Root);AssertBatchDisk(disk,ids);Check(lastBatchResult.Selected==count&&lastBatchResult.Success==count&&lastBatchResult.Skipped==0&&disk.Data.sequence==seq+1,"exact result and one commit");Check(disk.Data.entities.Count(e=>e.kind=="Review")==count,"one review per target");});
    test("selection/cross-scroll-preserves-exact-925-IDs",()=>{ShowBatchFixture(s);frames.SelectedIndex=1799;frames.SelectRange(875,1799,false);var before=new HashSet<string>(frames.SelectionIds());foreach(int i in new[]{875,1400,1799}){frames.ScrollIntoView(frames.Items[i]);Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));UpdateLayout();Check(frames.ItemContainerGenerator.ContainerFromIndex(i)!=null,"scroll target actually realized");Check(before.SetEquals(frames.SelectionIds()),"virtualization keeps selection");}Check(before.SetEquals(targets)&&frames.SelectedIndex==1799,"no CurrentFrame substitution or offset");});
    test("batch/925-mixed-protected-last-frame-progress-and-database",()=>{
     var protectedIds=new[]{all[900].id,all[1100].id,all[1799].id};var protectedBefore=s.Data.entities.Where(e=>protectedIds.Contains(e.id)||protectedIds.Contains(e.Text("frame_id"))||e.kind=="ROI").ToDictionary(e=>e.id,Codec.Json);
     string[] eligible=targets.Except(protectedIds).ToArray();long seq=s.Data.sequence;var source=frames.ItemsSource;int ticks=0;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(1)};timer.Tick+=(a,b)=>ticks++;timer.Start();var watch=Stopwatch.StartNew();BatchClick();BatchNormal();Check(busy,"duplicate ignored while worker active");WaitHotfix();timer.Stop();var disk=new Store(root);
     Check(lastBatchResult.Selected==925&&lastBatchResult.Success==922&&lastBatchResult.Skipped==3&&lastBatchResult.Failed==0,"925 = 922 + 3 + 0");AssertBatchDisk(disk,eligible);Check(disk.Data.sequence==seq+1,"single atomic write");Check(protectedBefore.All(p=>Codec.Json(disk.Find(p.Key))==p.Value),"protected geometry/frame/review/ROI bytes retained");Check(all.Take(875).All(f=>Codec.Json(disk.Find(f.id))==Codec.Json(f)),"nothing outside UUID selection changed");Check(DiskConfirmed(disk)==1129&&visibleConfirmedCount==1129&&frameSummary.Text=="已确认 1129 / 1800","persisted confirmed count agrees with UI");Check(Object.ReferenceEquals(source,frames.ItemsSource)&&frame.id==all[1799].id,"no list rebuild or last-frame advance");Check(eligible.All(id=>frameChoices[id].Name.Contains("正常")),"row labels refreshed");Check(batchFeedback.Text.Contains("选中925帧；成功标记922帧；跳过3帧；失败0帧。"),"persistent visible result");Check(ticks>0,"dispatcher timer responsive during batch");
     File.WriteAllText(Path.Combine(output,"925-details.json"),Codec.Json(new{selected=925,success=922,skipped=3,failed=0,confirmed=1129,total=1800,first_seconds=875,last_seconds=1799,elapsed_ms=watch.Elapsed.TotalMilliseconds,dispatcher_ticks=ticks,sequence_commits=1,selected_ids=targets,eligible_ids=eligible,skip_reasons=lastBatchResult.SkipReasons}));
     File.WriteAllText(Path.Combine(output,"expected.json"),Codec.Json(new{fingerprint=Codec.Fingerprint(disk.Data),confirmed=1129}));
    });
    test("batch/repeated-925-no-extra-revisions",()=>{string before=Codec.Fingerprint(new Store(root).Data);BatchClick();WaitHotfix();Check(lastBatchResult.Selected==925&&lastBatchResult.Success==0&&lastBatchResult.Skipped==925&&lastBatchResult.Failed==0,"all repeated targets skipped");Check(before==Codec.Fingerprint(new Store(root).Data),"no duplicate commits/revisions");});
    test("batch/925-all-eligible-and-last-frame-single-commit",()=>{var f=BatchFixture(Path.Combine(output,"925-clean"),1800);ShowBatchFixture(f);frames.SelectedIndex=1799;frames.SelectRange(875,1799,false);var ids=frames.SelectionIds();long sequence=f.Data.sequence;BatchClick();WaitHotfix();var disk=new Store(f.Root);AssertBatchDisk(disk,ids);Check(lastBatchResult.Selected==925&&lastBatchResult.Success==925&&lastBatchResult.Skipped==0&&lastBatchResult.Failed==0&&disk.Data.sequence==sequence+1&&DiskConfirmed(disk)==925,"all 925 saved once including last frame");});
    test("batch/last-unannotated-frame-participates",()=>{var f=BatchFixture(Path.Combine(output,"last-frame"),6);ShowBatchFixture(f);frames.SelectedIndex=5;frames.SelectRange(4,5,false);var ids=frames.SelectionIds();BatchClick();WaitHotfix();AssertBatchDisk(new Store(f.Root),ids);Check(lastBatchResult.Success==2&&frame.id==orderedFrames.Last().id,"last frame does not early-return");});
    test("batch/duplicate-UUIDs-deduplicated",()=>{var f=BatchFixture(Path.Combine(output,"dedup"),6);string id=f.Data.entities.First(e=>e.kind=="Frame").id;var r=new BatchNormalResult();f.MarkNormalBatchEligible(new[]{id,id,id},"test",r);var disk=new Store(f.Root);Check(r.Selected==1&&r.Success==1&&disk.Data.entities.Count(e=>e.kind=="Review")==1,"unique target one review");});
    test("batch/soft-delete-and-explicit-review-lock-protected",()=>{var f=BatchFixture(Path.Combine(output,"locks"),6);var fs=f.Data.entities.Where(e=>e.kind=="Frame").ToArray();fs[0].data["review_locked"]=true;f.Save();f.SetQueueDeleted(new[]{fs[1].id},true,"test");string a=Codec.Json(f.Find(fs[0].id)),b=Codec.Json(f.Find(fs[1].id));var r=new BatchNormalResult();f.MarkNormalBatchEligible(fs.Take(3).Select(e=>e.id),"test",r);var disk=new Store(f.Root);Check(r.Selected==3&&r.Success==1&&r.Skipped==2&&Codec.Json(disk.Find(fs[0].id))==a&&Codec.Json(disk.Find(fs[1].id))==b,"locked/deleted retained");});
    test("batch/pending-current-draft-does-not-block-other-frames",()=>{var f=BatchFixture(Path.Combine(output,"draft"),6);ShowBatchFixture(f);frames.SelectedIndex=5;polygon.Add(new Point(1,1));reviewEdited=true;frames.SelectRange(2,5,false);var ids=frames.SelectionIds().Where(id=>id!=frame.id).ToArray();string draft=frame.id;BatchClick();WaitHotfix();AssertBatchDisk(new Store(f.Root),ids);Check(lastBatchResult.Success==3&&lastBatchResult.Skipped==1&&polygon.Count==1&&reviewEdited&&frame.id==draft,"draft protected locally, other targets saved without per-frame save");polygon.Clear();reviewEdited=false;});
    test("batch/write-lock-exception-rolls-back-all-eligible-and-reports",()=>{var f=BatchFixture(Path.Combine(output,"write-failure"),6);ShowBatchFixture(f);frames.SelectRange(0,2,false);string before=Codec.Fingerprint(f.Data);using(var hold=new FileStream(Path.Combine(f.Root,".write.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){BatchClick();WaitHotfix();}Check(lastBatchResult.Selected==3&&lastBatchResult.Success==0&&lastBatchResult.Skipped==0&&lastBatchResult.Failed==3,"failure count actual rollback");Check(before==Codec.Fingerprint(new Store(f.Root).Data)&&before==Codec.Fingerprint(f.Data),"memory/disk transaction rollback");Check(batchFeedback.Text.Contains("失败3帧")&&batchFeedback.Text.Contains("原因：项目写入失败"),"Chinese failure visible");});
    test("batch/post-commit-UI-failure-keeps-actual-success-count",()=>{var f=BatchFixture(Path.Combine(output,"post-commit-ui-failure"),6);ShowBatchFixture(f);var ids=f.Data.entities.Where(e=>e.kind=="Frame").Take(3).Select(e=>e.id).ToArray();var r=new BatchNormalResult{Selected=3};Run("提交后界面异常回归",()=>f.MarkNormalBatchEligible(ids,"test",r),saved=>{throw new InvalidOperationException("注入的列表刷新异常");},e=>BatchNormalFailed(r,e));WaitHotfix();AssertBatchDisk(new Store(f.Root),ids);Check(r.Success==3&&r.Skipped==0&&r.Failed==0&&batchFeedback.Text.Contains("数据已提交")&&batchFeedback.Text.Contains("失败0帧"),"UI refresh exception never lies about committed results");});
    test("batch/pre-replace-failure-rolls-back-mixed-statistics",()=>{var f=BatchFixture(Path.Combine(output,"pre-replace-failure"),6);var fs=f.Data.entities.Where(e=>e.kind=="Frame").ToArray();f.ReviewCurrent(fs[0].id,"normal","confirmed","fixture");string before=Codec.Fingerprint(f.Data);var r=new BatchNormalResult();bool rejected=false;Work.Configure(()=>false,msg=>{if(msg=="HOTFIX_COMMIT_PRE_REPLACE")throw new IOException("注入的写盘异常");});try{f.MarkNormalBatchEligible(fs.Take(3).Select(e=>e.id),"test",r);}catch(IOException){rejected=true;}finally{Work.Configure(null,null);}Check(rejected&&r.Selected==3&&r.Success==0&&r.Skipped==1&&r.Failed==2,"X+Y+Z exact on rollback");Check(before==Codec.Fingerprint(new Store(f.Root).Data)&&before==Codec.Fingerprint(f.Data)&&Directory.GetFiles(f.Root,"*.tmp").Length==0,"actual flushed temp cleaned, committed store unchanged");});
    test("batch/cancellation-before-commit-is-atomic",()=>{var f=BatchFixture(Path.Combine(output,"cancel"),6);string before=Codec.Fingerprint(f.Data);var r=new BatchNormalResult();bool cancelled=false;Work.Configure(()=>false,msg=>{if(msg=="HOTFIX_COMMIT_PRE_REPLACE")throw new OperationCanceledException();});try{f.MarkNormalBatchEligible(f.Data.entities.Where(e=>e.kind=="Frame").Select(e=>e.id).ToArray(),"test",r);}catch(OperationCanceledException){cancelled=true;}finally{Work.Configure(null,null);}Check(cancelled&&r.Success==0&&r.Failed==6&&before==Codec.Fingerprint(new Store(f.Root).Data),"cancel result and rollback");});
    test("batch/pending-filter-removes-committed-rows-once",()=>{var f=BatchFixture(Path.Combine(output,"filter"),6);ShowBatchFixture(f);frameStateFilter.SelectedIndex=1;frames.SelectRange(0,2,false);BatchClick();WaitHotfix();Check(DiskConfirmed(new Store(f.Root))==3&&frames.Items.Count==3&&visibleConfirmedCount==0,"pending list and actual storage agree");frameStateFilter.SelectedIndex=0;Check(frameSummary.Text=="已确认 3 / 6","all-state counter exact");});
   }
   ticker.Stop();Close();return failed==0?0:1;
  }
 }
}
